'use strict';
const gripEditor=document.createElement('details');gripEditor.innerHTML='<summary>Adjust an existing grip</summary><select id="existingGrip" aria-label="Existing grip"></select><p class="note">Choose a grip, preview its time, then drag the object in this preview. The object stays attached to the hand. Undo restores the previous placement.</p><label>Grip X<input id="existingGripX" type="number" min="-200" max="200"></label><label>Grip Y<input id="existingGripY" type="number" min="-200" max="200"></label><label>Grip angle<input id="existingGripAngle" type="number" min="-360" max="360"></label>';$('propInteractionStatus').before(gripEditor);
function selectedExistingGrip(){return(current().propInteractions||[]).find(i=>i.id===$('existingGrip').value)}
function checkExistingGrip(i){if(!i)throw Error('Choose an existing grip.');if([i.actorId,i.otherId,i.propId].some(id=>current().objects.find(o=>o.id===id)?.locked))throw Error('Unlock the character and object before adjusting the grip.')}
function fillExistingGrip(){const i=selectedExistingGrip();for(const [id,key]of [['existingGripX','x'],['existingGripY','y']])$(id).value=i?.offset[key]||0;$('existingGripAngle').value=i?.rotation||0}
const interactionsBeforeGripEditing=renderInteractionTools;renderInteractionTools=function(){const previous=$('existingGrip').value;interactionsBeforeGripEditing();const list=$('existingGrip');list.replaceChildren();for(const i of current().propInteractions||[]){if(['point','release'].includes(i.kind))continue;const option=document.createElement('option');option.value=i.id;option.textContent=(current().objects.find(o=>o.id===i.propId)?.name||'Object')+' · '+i.hand+' hand · '+i.start.toFixed(1)+'s';list.append(option)}if([...list.options].some(o=>o.value===previous))list.value=previous;fillExistingGrip()};
$('existingGrip').onchange=()=>{const i=selectedExistingGrip();fillExistingGrip();if(i){time=Math.min(current().duration,i.start+i.duration);$('propInteractionTime').value=time;paintInteractionPreview()}};
for(const [id,key]of [['existingGripX','x'],['existingGripY','y'],['existingGripAngle','rotation']])$(id).onchange=()=>{try{const i=selectedExistingGrip();checkExistingGrip(i);const value=+$(id).value;if(!Number.isFinite(value))return;if(key==='rotation')i.rotation=clamp(value,-360,360);else i.offset[key]=clamp(value,-200,200);save();paintInteractionPreview();fillExistingGrip()}catch(e){toast(e.message)}};
$('propInteractionPreview').addEventListener('pointerdown',e=>{if(e.button)return;const i=selectedExistingGrip();if(!i)return;try{checkExistingGrip(i)}catch(error){return toast(error.message)}const canvas=e.currentTarget,rect=canvas.getBoundingClientRect(),view=projectView(),start={...i.offset},x=e.clientX,y=e.clientY;if(time<i.start)time=Math.min(current().duration,i.start+i.duration);e.preventDefault();canvas.setPointerCapture(e.pointerId);window.editorTaskBusy=true;let moved=false;canvas.onpointermove=event=>{moved||=Math.hypot(event.clientX-x,event.clientY-y)>2;const cam=cameraAt(current(),time),owner=propEventOwner(i,time),actor=current().objects.find(o=>o.id===owner?.actorId),hand=actor&&interactionHand(actor,stateAt(actor,time),owner.hand),angle=i.followRotation?(hand?.angle||0)*Math.PI/180:0,dx=(event.clientX-x)/rect.width*960/(cam.zoom||1),dy=(event.clientY-y)/rect.height*540/(cam.zoom||1);i.offset.x=clamp(start.x+dx*Math.cos(angle)+dy*Math.sin(angle),-200,200);i.offset.y=clamp(start.y+dy*Math.cos(angle)-dx*Math.sin(angle),-200,200);fillExistingGrip();paintInteractionPreview()};const finish=cancel=>{canvas.onpointermove=canvas.onpointerup=canvas.onpointercancel=null;window.editorTaskBusy=false;if(cancel)i.offset=start;else if(moved)save();fillExistingGrip();paintInteractionPreview()};canvas.onpointerup=()=>finish(false);canvas.onpointercancel=()=>finish(true)});
